pub fn arccosh(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    assert!(n > 0, "input vector must be non-empty");

    let mut result: Vec<f32> = Vec::with_capacity(n);
    let mut i: usize = 0;

    while i < n {
        let v = x[i];
        // Fixed unary transformation applied in order.
        result.push(v.acosh());
        i += 1;
    }

    debug_assert_eq!(result.len(), n);
    result
}